    bonds: [
      { nome: 'Choque de Vontades', bonus: 'Shaka e Aiolia ganham 18% de Velocidade de Ataque.', membros: [{ icone: 'CircleHead/CircleHeroHead_10710.png', codexId: '1082', nome: 'Shaka de Virgem' }, { icone: 'CircleHead/CircleHeroHead_10100.png', codexId: '1003', nome: 'Aiolia de Leão' }], nome_en: 'Clash of Wills', bonus_en: 'Participants ATK SPD increased by 18%', nome_es: 'Choque de Voluntades', bonus_es: 'Shaka y Aioria ganan 18% de Velocidad de Ataque.' },
      { nome: 'Afeição Fraternal', bonus: 'A resist. a crít. de Aiolia e Aiolos aumenta em 10%', membros: [{ icone: 'CircleHead/CircleHeroHead_10100.png', codexId: '1003', nome: 'Aiolia de Leão' }, { icone: 'CircleHead/CircleHeroHead_10510.png', codexId: '1004', nome: 'Aiolos de Sagitário' }], nome_en: 'Brotherly Affection', bonus_en: 'Aiolia and Aiolos Crit Resist increases by 10%', nome_es: 'Afecto Fraternal', bonus_es: 'Aioria y Aioros incrementa la Resistencia Crítica en 10%' },
      { nome: 'Vontade Herdada', bonus: 'Quando Aiolia causa dano físico a um inimigo, há uma chance de 5% de infligir um efeito de queimadura no inimigo, durando 7,5 segundos e causando 10% de dano psíquico a cada 2,5 segundos. A taxa de crít. de Ikki de Leão aumenta em 10%.', membros: [{ icone: '', codexId: '1034', nome: 'Ikki de Leão' }, { icone: 'CircleHead/CircleHeroHead_10100.png', codexId: '1003', nome: 'Aiolia de Leão' }], nome_en: 'Inherited Will', bonus_en: 'When Aiolia deals P-DMG to an enemy, there is a 5% chance to inflict a Burn effect on the enemy, lasting 7.5 seconds and causing 10% Mental DMG every 2.5 seconds. Leo Ikki\'s Crit Rate is increased by 10%.', nome_es: 'Voluntad Heredada', bonus_es: 'Cuando Aioria inflige DAÑO Físico a un enemigo, se tiene un 5% de probabilidad de infligir un efecto de Quemadura en el enemigo, dura 7,5 seg y causa 10% de DAÑO Mental cada 2,5 seg. El Índice Crítico de Ikki de Leo se incrementa en 10%.' },
      { nome: 'Leão no Caminho', bonus: 'O Laimi de Verme e Aiolia têm o aumento de quantidade de cura recebida em 25%.', membros: [{ icone: 'CircleHead/CircleHeroHead_10330.png', codexId: '1101', nome: 'Laimi de Verme' }, { icone: 'CircleHead/CircleHeroHead_10100.png', codexId: '1003', nome: 'Aiolia de Leão' }], nome_en: 'Lion Blocking the Way', bonus_en: 'Healing received by Worm Raimi and Aiolia is increased by 25%.', nome_es: 'León Bloqueando el Camino', bonus_es: 'Incrementa la Curación recibida por Raimi de Estrella Agazapada de Tierra y Aioria en 25%.' },
      { nome: 'Campeão da Justiça', bonus: 'PV: +1% | Ataque: +1%', membros: [{ icone: 'CircleHead/CircleHeroHead_10510.png', codexId: '1004', nome: 'Aiolos de Sagitário' }], nome_en: 'Champion of Justice', bonus_en: 'HP: +1% | Attack: +1%', nome_es: 'Campeón de la Justicia', bonus_es: 'HP: +1% | Ataque: +1%' },
      { nome: 'Aliado Dourado', bonus: 'PV: +2% | Ataque: +2%', membros: [{ icone: 'CircleHead/CircleHeroHead_10070.png', codexId: '1059', nome: 'Mu de Áries' }, { icone: 'CircleHead/CircleHeroHead_10490.png', codexId: '1054', nome: 'Milo de Escorpião' }], nome_en: 'Golden Ally', bonus_en: 'HP: +2% | Attack: +2%', nome_es: 'Aliado Dorado', bonus_es: 'HP: +2% | Ataque: +2%' },
      { nome: 'Campeão da Deusa', bonus: 'PV: +3% | Ataque: +3%', membros: [{ icone: 'CircleHead/CircleHeroHead_10110.png', codexId: '1080', nome: 'Seiya de Pégaso' }, { icone: 'CircleHead/CircleHeroHead_10230.png', codexId: '1081', nome: 'Shaina de Ofiúco' }, { icone: 'CircleHead/CircleHeroHead_10060.png', codexId: '1076', nome: 'Saori Kido' }], nome_en: 'Goddess\'s Champion', bonus_en: 'HP: +3% | Attack: +3%', nome_es: 'Campeón de la Diosa', bonus_es: 'HP: +3% | Ataque: +3%' },
      { nome: 'Defendendo o Santuário', bonus: 'PV: +4% | Ataque: +4%', membros: [{ icone: 'CircleHead/CircleHeroHead_10090.png', codexId: '1074', nome: 'Saga de Gêmeos' }, { icone: 'CircleHead/CircleHeroHead_10710.png', codexId: '1082', nome: 'Shaka de Virgem' }, { icone: 'CircleHead/CircleHeroHead_10900.png', codexId: '1016', nome: 'Cassios' }, { icone: 'CircleHead/CircleHeroHead_10330.png', codexId: '1101', nome: 'Laimi de Verme' }], nome_en: 'Defending Sanctuary', bonus_en: 'HP: +4% | Attack: +4%', nome_es: 'Santuario Defensor', bonus_es: 'HP: +4% | Ataque: +4%' }
    ]
