    bonds: [
      { nome: 'Gêmeos Oponentes', bonus: 'Kanon de Dragão Marinho ganha 15% de aumento da taxa de recuperação de ira após o início da batalha; Saga de Gêmeos ganha 200 de ira adicional após o início da batalha', membros: [{ icone: 'CircleHead/CircleHeroHead_10210.png', codexId: '1042', nome: 'Kanon de Dragão Marinho' }, { icone: 'CircleHead/CircleHeroHead_10090.png', codexId: '1074', nome: 'Saga de Gêmeos' }], nome_en: 'Opposing Gemini', bonus_en: 'Sea Dragon Kanon gains increased Rage Recovery Rate by 15% after the battle begins; Gemini Saga gains 200 additional Rage after the battle begins', nome_es: 'Géminis Rebelde', bonus_es: 'Kanon del Dragón Marino gana un índice de Recuperación de Ira incrementado en 15% después de que comience la batalla; Saga de Géminis gana 200 de Ira adicional después de que comience la batalla' },
      { nome: 'Tríade de Atlântida', bonus: 'Kanon de Dragão Marinho, Krishna de Chrysaor e Sorento de Sirene: Após o início da batalha, a VEL de habilidade aumenta em 15%; a redução de dano físico e redução de dano psíquico aumentam em 25%, durando 10 segundos.', membros: [{ icone: 'CircleHead/CircleHeroHead_10210.png', codexId: '1042', nome: 'Kanon de Dragão Marinho' }, { icone: 'CircleHead/CircleHeroHead_10170.png', codexId: '1046', nome: 'Krishna de Chrysaor' }, { icone: 'CircleHead/CircleHeroHead_10200.png', codexId: '1095', nome: 'Sorento de Sirene' }], nome_en: 'Marine Generals', bonus_en: 'Sea Dragon Kanon, Chrysaor Krishna, and Siren Sorrento: After the battle begins, skill speed increases by 15%; Physical DMG Reduction and Mental DMG Reduction increase by 25%, lasting 10 seconds.', nome_es: 'Tríada de Atlántida', bonus_es: 'Kanon del Dragón Marino, Krishna de Crisaor y Sorrento de Sirena: Después de que comience la batalla, la velocidad de habilidad incrementa en 15%; la Reducción de DAÑO Físico y la Reducción de DAÑO Mental incrementan en 25%, durando 10 seg.' },
      { nome: 'Retribuição Dourada', bonus: 'O roubo de vida de dano da Habilidade Suprema de Kanon de Dragão Marinho e Milo aumenta em 30%.', membros: [{ icone: 'CircleHead/CircleHeroHead_10210.png', codexId: '1042', nome: 'Kanon de Dragão Marinho' }, { icone: 'CircleHead/CircleHeroHead_10490.png', codexId: '1054', nome: 'Milo de Escorpião' }], nome_en: 'Golden Retribution', bonus_en: 'Sea Dragon Kanon and Milo\'s Ultimate Skill Damage Lifesteal is increased by 30%.', nome_es: 'Retribución Dorada', bonus_es: 'El Robo de Vida de Daño de Habilidad Definitiva de Kanon del Dragón Marino y Milo se incrementa en 30%.' },
      { nome: 'Engane os Deuses', bonus: 'A duração dos estados de controle aplicados por Kanon de Dragão Marinho e Juliano aumenta em 10%, e o roubo de vida de dano aumenta em 8%.', membros: [{ icone: 'CircleHead/CircleHeroHead_10210.png', codexId: '1042', nome: 'Kanon de Dragão Marinho' }, { icone: 'CircleHead/CircleHeroHead_10730.png', codexId: '1040', nome: 'Julian Solo' }], nome_en: 'Deceive the Gods', bonus_en: 'The duration of Control States applied by Sea Dragon Kanon and Julian is increased by 10%, and Damage Lifesteal is increased by 8%.', nome_es: 'Engañar a los Dioses', bonus_es: 'La duración de los Estados de Control aplicados por Kanon del Dragón Marino y Julian incrementa en 10%, y el Robo de Vida de Daño incrementa en 8%.' },
      { nome: 'A Redenção do Semideus', bonus: 'Quando Kanon de Gêmeos e Kanon de Dragão Marinho aplicam Outra Dimensão, Dano de Habilidade +15% por 10s.', membros: [{ icone: 'CircleHead/CircleHeroHead_11080.png', codexId: '1043', nome: 'Kanon de Gêmeos' }, { icone: 'CircleHead/CircleHeroHead_10210.png', codexId: '1042', nome: 'Kanon de Dragão Marinho' }], nome_en: 'The Demigod\'s Redemption', bonus_en: 'When Gemini Kanon and Sea Dragon Kanon apply Another Dimension, Skill DMG +15% for 10s.', nome_es: 'La Redención del Semidiós', bonus_es: 'Cuando Kanon de Géminis y Kanon de Dragón Marino aplican Otra Dimensión, el DAÑO de Habilidad +15% durante 10s.' },
      { nome: 'Irmão Mau', bonus: 'PV: +1% | Ataque: +1%', membros: [{ icone: 'CircleHead/CircleHeroHead_10090.png', codexId: '1074', nome: 'Saga de Gêmeos' }], nome_en: 'Bad Brother', bonus_en: 'HP: +1% | Attack: +1%', nome_es: 'Hermano Malo', bonus_es: 'HP: +1% | Ataque: +1%' },
      { nome: 'Inimigo Impiedoso', bonus: 'PV: +2% | Ataque: +2%', membros: [{ icone: 'CircleHead/CircleHeroHead_10050.png', codexId: '1036', nome: 'Ikki de Fênix' }, { icone: 'CircleHead/CircleHeroHead_10280.png', codexId: '1073', nome: 'Radamanthys de Wyvern' }], nome_en: 'Ruthless Enemy', bonus_en: 'HP: +2% | Attack: +2%', nome_es: 'Enemigo Implacable', bonus_es: 'HP: +2% | Ataque: +2%' },
      { nome: 'Pecados do Mar', bonus: 'PV: +3% | Ataque: +3%', membros: [{ icone: 'CircleHead/CircleHeroHead_10490.png', codexId: '1054', nome: 'Milo de Escorpião' }, { icone: 'CircleHead/CircleHeroHead_10200.png', codexId: '1095', nome: 'Sorento de Sirene' }, { icone: 'CircleHead/CircleHeroHead_10130.png', codexId: '1071', nome: 'Poseidon' }], nome_en: 'Sins of the Sea', bonus_en: 'HP: +3% | Attack: +3%', nome_es: 'Pecados del Mar', bonus_es: 'HP: +3% | Ataque: +3%' },
      { nome: 'Dever Fraterno', bonus: 'PV: +4% | Ataque: +4%', membros: [{ icone: 'CircleHead/CircleHeroHead_10900.png', codexId: '1016', nome: 'Cassios' }, { icone: 'CircleHead/CircleHeroHead_10040.png', codexId: '1091', nome: 'Shun de Andrômeda' }, { icone: 'CircleHead/CircleHeroHead_10650.png', codexId: '1083', nome: 'Shido de Mizar, a Estrela Zeta' }, { icone: 'CircleHead/CircleHeroHead_10100.png', codexId: '1003', nome: 'Aiolia de Leão' }], nome_en: 'Fraternal Duty', bonus_en: 'HP: +4% | Attack: +4%', nome_es: 'Deber Fraternal', bonus_es: 'HP: +4% | Ataque: +4%' }
    ]
