    bonds: [
      { nome: 'Liberte o Verdadeiro Deus', bonus: 'O dano Psíquico e Físico causado por Pandora, Comandante do Submundo, Hypnos, o Deus do Sono e Thanatos, o Deus da Morte é aumentado em 8%, e a quantidade de cura é aumentada em 8%.', membros: [{ icone: 'CircleHead/CircleHeroHead_10560.png', codexId: '1064', nome: 'Pandora, a Comandante do Submundo' }, { icone: 'CircleHead/CircleHeroHead_10260.png', codexId: '1032', nome: 'Hypnos, o Deus do Sono' }, { icone: 'CircleHead/CircleHeroHead_10270.png', codexId: '1098', nome: 'Thanatos, o Deus da Morte' }], nome_en: 'Unleash the True God', bonus_en: 'Pandora, Underworld Commander, Hypnos, God of Sleep, and Thanatos, God of Death deals 8% more M-DMG and P-DMG and provide 8% more healing.', nome_es: 'Libera al Dios Verdadero', bonus_es: 'Pandora, Comandante del Inframundo, Hypnos, Dios del Sueño y Thanatos, Dios de la Muerte infligen un 8% más de DAÑO-M y DAÑO-F y proporcionan un 8% más de curación.' },
      { nome: 'Falsos Irmãos', bonus: 'PV: +1% | Ataque: +1%', membros: [{ icone: '', codexId: '1090', nome: 'Shun possuído por Hades' }], nome_en: 'False Siblings', bonus_en: 'HP: +1% | Attack: +1%', nome_es: 'Falsos Hermanos', bonus_es: 'HP: +1% | Ataque: +1%' },
      { nome: 'Liberando o Verdadeiro Deus', bonus: 'PV: +2% | Ataque: +2%', membros: [{ icone: 'CircleHead/CircleHeroHead_10260.png', codexId: '1032', nome: 'Hypnos, o Deus do Sono' }, { icone: 'CircleHead/CircleHeroHead_10270.png', codexId: '1098', nome: 'Thanatos, o Deus da Morte' }], nome_en: 'Unleashing the True God', bonus_en: 'HP: +2% | Attack: +2%', nome_es: 'Liberando al Dios Verdadero', bonus_es: 'HP: +2% | Ataque: +2%' },
      { nome: 'Relíquia de Atena', bonus: 'PV: +3% | Ataque: +3%', membros: [{ icone: 'CircleHead/CircleHeroHead_10830.png', codexId: '1021', nome: 'Saga de Gêmeos Sapuri' }, { icone: 'CircleHead/CircleHeroHead_10840.png', codexId: '1092', nome: 'Shura de Capricórnio Sapuri' }, { icone: 'CircleHead/CircleHeroHead_10850.png', codexId: '1014', nome: 'Camus de Aquário Sapuri' }], nome_en: 'Athena\'s Relic', bonus_en: 'HP: +3% | Attack: +3%', nome_es: 'Reliquia de Atenea', bonus_es: 'HP: +3% | Ataque: +3%' },
      { nome: 'Canção de Sirene', bonus: 'PV: +4% | Ataque: +4%', membros: [{ icone: 'CircleHead/CircleHeroHead_10550.png', codexId: '1063', nome: 'Orfeu de Lira' }, { icone: 'CircleHead/CircleHeroHead_10200.png', codexId: '1095', nome: 'Sorento de Sirene' }, { icone: '', codexId: '1070', nome: 'Faraó de Esfinge, a Estrela Besta Celestial' }, { icone: 'CircleHead/CircleHeroHead_10640.png', codexId: '1055', nome: 'Mime de Benetnasch, a Estrela Eta' }], nome_en: 'Siren\'s Song', bonus_en: 'HP: +4% | Attack: +4%', nome_es: 'Canto de Sirena', bonus_es: 'HP: +4% | Ataque: +4%' }
    ]
