    bonds: [
      { nome: 'Conflito entre o Bem e o Mal', bonus: 'Saga, a Encarnação do Mal e Saga de Gêmeos ganham 20% de VEL de Habilidade.', membros: [{ icone: 'CircleHead/CircleHeroHead_10720.png', codexId: '1075', nome: 'Saga, a Encarnação do Mal' }, { icone: 'CircleHead/CircleHeroHead_10090.png', codexId: '1074', nome: 'Saga de Gêmeos' }], nome_en: 'Conflict between Good and Evil', bonus_en: 'The skill speed of Evil Saga and Gemini Saga increased by 20%', nome_es: 'Conflicto entre el Bien y el Mal', bonus_es: 'Encarnación de Saga Maligno y Saga de Géminis ganan 20% de VEL de Habilidad.' },
      { nome: 'Dois Lados da Mesma Moeda', bonus: 'A duração do Controle de Saga, a Encarnação do Mal e de Ares aumenta em 15%.', membros: [{ icone: 'CircleHead/CircleHeroHead_10720.png', codexId: '1075', nome: 'Saga, a Encarnação do Mal' }, { icone: 'CircleHead/CircleHeroHead_10750.png', codexId: '1065', nome: 'Papa Ares' }], nome_en: 'Two Sides of the Same Coin', bonus_en: 'The control effect duration of Evil Saga and Ares increased by 15%', nome_es: 'Dos Caras de la Misma Moneda', bonus_es: 'La duración del control de Encarnación de Saga Maligno y Ares incrementa en 15%.' },
      { nome: 'Luta pelo Poder', bonus: 'PV: +1% | Ataque: +1%', membros: [{ icone: 'CircleHead/CircleHeroHead_10740.png', codexId: '1084', nome: 'Shion de Áries' }], nome_en: 'Power Struggle', bonus_en: 'HP: +1% | Attack: +1%', nome_es: 'Lucha de Poder', bonus_es: 'HP: +1% | Ataque: +1%' },
      { nome: 'Tentação Sombria', bonus: 'PV: +2% | Ataque: +2%', membros: [{ icone: 'CircleHead/CircleHeroHead_10750.png', codexId: '1065', nome: 'Papa Ares' }, { icone: 'CircleHead/CircleHeroHead_10210.png', codexId: '1042', nome: 'Kanon de Dragão Marinho' }], nome_en: 'Dark Temptation', bonus_en: 'HP: +2% | Attack: +2%', nome_es: 'Tentación Oscura', bonus_es: 'HP: +2% | Ataque: +2%' },
      { nome: 'Punho Fantasma', bonus: 'PV: +3% | Ataque: +3%', membros: [{ icone: 'CircleHead/CircleHeroHead_10100.png', codexId: '1003', nome: 'Aiolia de Leão' }, { icone: 'CircleHead/CircleHeroHead_11030.png', codexId: '1026', nome: 'Guilty' }, { icone: 'CircleHead/CircleHeroHead_10390.png', codexId: '1053', nome: 'Cavaleiro de Cristal' }], nome_en: 'Phantom Fist', bonus_en: 'HP: +3% | Attack: +3%', nome_es: 'Puñetazo Espectral', bonus_es: 'HP: +3% | Ataque: +3%' },
      { nome: 'Destruidor da Conspiração', bonus: 'PV: +4% | Ataque: +4%', membros: [{ icone: 'CircleHead/CircleHeroHead_10110.png', codexId: '1080', nome: 'Seiya de Pégaso' }, { icone: 'CircleHead/CircleHeroHead_10060.png', codexId: '1076', nome: 'Saori Kido' }, { icone: 'CircleHead/CircleHeroHead_10050.png', codexId: '1036', nome: 'Ikki de Fênix' }, { icone: 'CircleHead/CircleHeroHead_10090.png', codexId: '1074', nome: 'Saga de Gêmeos' }], nome_en: 'Conspiracy Crusher', bonus_en: 'HP: +4% | Attack: +4%', nome_es: 'Destructor de Conspiraciones', bonus_es: 'HP: +4% | Ataque: +4%' }
    ]
