      { nome: 'Soco do Grito do Coração', bonus: 'PV: +2% | Ataque: +2%', membros: [{ icone: 'CircleHead/CircleHeroHead_10040.png', codexId: '1091', nome: 'Shun de Andrômeda' }, { icone: 'CircleHead/CircleHeroHead_10050.png', codexId: '1036', nome: 'Ikki de Fênix' }], nome_en: 'Cry of the Heart Punch', bonus_en: 'HP: +2% | Attack: +2%' },
      { nome: 'Laço Inquebrável', bonus: 'PV: +3% | Ataque: +3%', membros: [{ icone: 'CircleHead/CircleHeroHead_10250.png', codexId: '1027', nome: 'Hades, Rei do Submundo' }, { icone: 'CircleHead/CircleHeroHead_10560.png', codexId: '1064', nome: 'Pandora, a Comandante do Submundo' }, { icone: 'CircleHead/CircleHeroHead_10050.png', codexId: '1036', nome: 'Ikki de Fênix' }], nome_en: 'Unbreakable Bond', bonus_en: 'HP: +3% | Attack: +3%' },
      { nome: 'Assassinato', bonus: 'PV: +4% | Ataque: +4%', membros: [{ icone: 'CircleHead/CircleHeroHead_10550.png', codexId: '1063', nome: 'Orfeu de Lira' }, { icone: 'CircleHead/CircleHeroHead_10280.png', codexId: '1073', nome: 'Radamanthys de Wyvern' }, { icone: 'CircleHead/CircleHeroHead_10110.png', codexId: '1080', nome: 'Seiya de Pégaso' }, { icone: 'CircleHead/CircleHeroHead_10040.png', codexId: '1091', nome: 'Shun de Andrômeda' }], nome_en: 'Assassination', bonus_en: 'HP: +4% | Attack: +4%' }
